(()=>{const e=e=>{e.querySelectorAll(".collapse").forEach(e=>{e.addEventListener("shown.bs.collapse",()=>{window.answerQuills&&Object.keys(answerQuills).forEach(o=>{e.querySelector("#"+o)&&answerQuills[o].mathField.reflow()})}),e.addEventListener("hide.bs.collapse",()=>{for(const o of e.querySelectorAll(".ww-feedback-btn"))bootstrap.Popover.getInstance(o)?.hide()})})};document.querySelectorAll(".section-div").forEach(e);new MutationObserver(o=>{o.forEach(o=>{o.addedNodes.forEach(o=>{o instanceof Element&&(o.classList.contains("section-div")?e(o):o.querySelectorAll(".section-div").forEach(e))})})}).observe(document.body,{childList:!0,subtree:!0})})();